sect1.programlisting:
SELECT ts2index(Instant) '2ef59bd352b93ac3@2001-01-01';
SELECT ts2index(SequenceSet) '{[2ef59bd352b93ac3@2001-01-01,
  2ef59bd352b93ac3@2001-01-02]}';
-- ERROR: temporal type (Instant) does not match column type (Sequence)
SELECT ts2index(Sequence) '2ef59bd352b93ac3@2001-01-01';
